(()=>{
const logo='data:image/png;base64,';document.documentElement.style.setProperty('--weekos-logo',`url("${logo}")`);
let fav=document.querySelector('link[rel="icon"]');if(!fav){fav=document.createElement('link');fav.rel='icon';document.head.appendChild(fav)}fav.href=logo;
// Preserve all original state and storage keys; refresh every dependent view on successful mutation.
const priorSave=save;
save=function(){let serialized;try{snapshotWeek();serialized=JSON.stringify(state);localStorage.setItem(KEY,serialized);if(localStorage.getItem(KEY)!==serialized)throw Error('Storage verification failed')}catch(e){toast('Save failed: '+e.message);return false}
 try{applyTheme();renderAll();if(page==='meals'||page==='themes')renderCustom(page);else if(page!=='today')showPage(page);renderProfile();}catch(e){console.error('WeekOS UI update failed',e);toast('Saved, but the view could not update: '+e.message);return false}
 toast('Saved successfully');return true};
// Display tasks and classes from their canonical records, without deriving status from the clock.
const originalRenderTasks=renderTasks;
renderTasks=function(){const day=todayISO(),tasks=state.tasks.filter(t=>t.date===day||(!t.date&&t.status!=='completed')),classes=todayClasses();
 const rows=[...tasks.map(t=>({kind:'task',id:t.id,title:t.title,meta:t.time||t.start||'',status:t.status==='completed'?'yes':t.status==='not_completed'||t.status==='absent'?'no':''})),...classes.map(c=>({kind:'class',id:c.id,title:course(c.courseId).name,meta:fmtHour(c.start)+'–'+fmtHour(c.end),status:attendanceFor(c)==='Attended'?'yes':attendanceFor(c)==='Absent'?'no':''}))];
 $('#quickTasks').innerHTML=rows.length?rows.map(r=>`<div class="woTodayItem"><div><strong><span class="woKind">${r.kind==='class'?'CLASS':'TASK'}</span>${esc(r.title)}</strong><small>${esc(r.meta)} · ${r.status==='yes'?(r.kind==='class'?'Attended':'Completed'):r.status==='no'?(r.kind==='class'?'Absent':'Not completed'):'Unmarked'}</small></div><div class="woStatusButtons"><button type="button" aria-label="Mark completed or attended" aria-pressed="${r.status==='yes'}" data-wo-status="${r.kind}|${r.id}|yes">✓</button><button type="button" aria-label="Mark not completed or absent" aria-pressed="${r.status==='no'}" data-wo-status="${r.kind}|${r.id}|no">✕</button><button type="button" aria-label="Clear status" aria-pressed="${r.status===''}" data-wo-status="${r.kind}|${r.id}|clear">–</button></div></div>`).join(''):'<div style="padding:15px;color:var(--muted)">No tasks or classes today.</div>';
 $('#taskCount').textContent=tasks.filter(t=>t.status!=='completed').length;
 $('#quickTasks').querySelectorAll('[data-wo-status]').forEach(b=>b.onclick=()=>{const [kind,id,choice]=b.dataset.woStatus.split('|');if(kind==='class'){const c=state.classes.find(c=>c.id===id);if(!c)return;const key=attendanceKey(c);if(choice==='clear')delete state.attendance[key];else state.attendance[key]=choice==='yes'?'Attended':'Absent'}else{const t=state.tasks.find(t=>t.id===id);if(!t)return;t.status=choice==='yes'?'completed':choice==='no'?'not_completed':'pending'}save()});
};
// Avoid the browser's AM/PM control: keep the custom 00–23 hour and 00–59 minute selectors.
// The existing meal form already constructs two independent 24-hour select controls.
// Provide a stable test surface without changing production interactions.
window.WeekOSVerification={state:()=>state,save:()=>save(),render:()=>renderAll(),meal:(name)=>state.meals.find(m=>m.title===name)};
renderAll();
})();